import random
import struct
import zlib
from typing import List

# This generator targets raw binary data for two fuzzing stubs:
# - lldpctl_recv: expects bytes as if received from lldpd. We'll emit plausible
#   framed messages that look like simple TLV sequences to exercise parser paths.
# - lldpctl_atom_set_buffer: accepts arbitrary buffers for various keys. We'll
#   also generate well-formed payloads commonly used by LLDP fields (MAC, IPv4,
#   IPv6, strings, VLAN TLVs, MED, 802.3 power, etc.).
# The buffers are valid-structured, not mutated, and <= 4096 bytes.

# Utilities to build small TLV-like structures

def _tlv(t: int, v: bytes) -> bytes:
    # Generic TLV: type(1), length(2, big-endian), value
    return struct.pack('>BH', t & 0xFF, len(v) & 0xFFFF) + v


def _mac(rand: random.Random) -> bytes:
    # Generate a locally administered unicast MAC by setting bits appropriately
    b = bytearray(rand.getrandbits(8) for _ in range(6))
    b[0] &= 0xFE  # unicast
    b[0] |= 0x02  # locally administered
    return bytes(b)


def _ipv4(rand: random.Random) -> bytes:
    # Avoid special/broadcast-only ranges sometimes, but keep valid
    octets = [rand.randint(1, 223), rand.randint(0, 255), rand.randint(0, 255), rand.randint(1, 254)]
    # Avoid 127.0.0.0/8
    if octets[0] == 127:
        octets[0] = 10
    return bytes(octets)


def _ipv6(rand: random.Random) -> bytes:
    return bytes(rand.getrandbits(8) for _ in range(16))


def _oui(rand: random.Random) -> bytes:
    return bytes(rand.getrandbits(8) for _ in range(3))


def _str(rand: random.Random, min_len=0, max_len=64) -> bytes:
    # ASCII friendly string for names/descriptions
    length = rand.randint(min_len, max_len)
    alphabet = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789 -_./:"
    return bytes(rand.choice(alphabet) for _ in range(length))


def _u16(rand: random.Random, lo=0, hi=65535) -> int:
    return rand.randint(lo, hi)


def _u32(rand: random.Random, lo=0, hi=0xFFFFFFFF) -> int:
    return rand.randint(lo, hi)


def _lldp_chassis_id(rand: random.Random) -> bytes:
    # subtype 4 = MAC address commonly used
    subtype = 4
    return struct.pack('>B', subtype) + _mac(rand)


def _lldp_port_id(rand: random.Random) -> bytes:
    # subtype 5 = interface name; subtype 3 = MAC
    if rand.random() < 0.5:
        subtype = 5
        name = _str(rand, 2, 12)
        return struct.pack('>B', subtype) + name
    else:
        subtype = 3
        return struct.pack('>B', subtype) + _mac(rand)


def _lldp_ttl(rand: random.Random) -> bytes:
    return struct.pack('>H', _u16(rand, 10, 120))


def _lldp_port_descr(rand: random.Random) -> bytes:
    return _str(rand, 0, 40)


def _lldp_sys_name(rand: random.Random) -> bytes:
    return _str(rand, 1, 32)


def _lldp_sys_descr(rand: random.Random) -> bytes:
    return _str(rand, 10, 80)


def _lldp_mgmt_addr(rand: random.Random) -> bytes:
    # Management Address TLV value format per 802.1AB:
    # mgmt addr len(1) incl AF+addr, AF num(1), addr(n), ifnum subtype(1), ifnum(4), oid len(1), oid(n)
    if rand.random() < 0.6:
        af = 1  # IPv4
        addr = _ipv4(rand)
    else:
        af = 2  # IPv6
        addr = _ipv6(rand)
    mgmt_len = 1 + len(addr)
    ifsub = 2  # ifIndex
    ifnum = _u32(rand, 1, 100000)
    oid = b""  # keep empty usually
    return struct.pack('>B', mgmt_len) + struct.pack('>B', af) + addr + struct.pack('>B', ifsub) + struct.pack('>I', ifnum) + struct.pack('>B', len(oid)) + oid


def _lldp_vlan_tlv(rand: random.Random) -> bytes:
    # IEEE 802.1 Port VLAN ID TLV (organizationally specific)
    # OUI + subtype + info: VLAN ID (2), name
    oui = b"\x00\x80\xc2"  # 802.1 OUI
    subtype = 3  # Port VLAN ID or VLAN Name; use VLAN Name (per common impls)
    vid = _u16(rand, 1, 4094)
    name = _str(rand, 0, 16)
    info = struct.pack('>H', vid) + name
    return _tlv(127, oui + struct.pack('>B', subtype) + info)


def _lldp_8023_power_tlv(rand: random.Random) -> bytes:
    # 802.3 PoE TLV (organizationally specific)
    oui = b"\x00\x12\x0f"  # 802.3 OUI
    subtype = 1  # Power via MDI
    # Simple fields: PSE or PD, power pair, class
    info = struct.pack('>B', rand.randint(0, 3)) + struct.pack('>B', rand.randint(0, 3)) + struct.pack('>B', rand.randint(0, 8))
    return _tlv(127, oui + struct.pack('>B', subtype) + info)


def _lldp_med_location_tlv(rand: random.Random) -> bytes:
    # LLDP-MED location TLV (TIA OUI 00-12-BB)
    oui = b"\x00\x12\xbb"
    subtype = 2  # Location Identification
    # Format: location format + location data (keep simple civic address element)
    fmt = 1  # coordinate-based(1) or civic(2); choose 1 with lat/long
    lat = rand.uniform(-90.0, 90.0)
    lon = rand.uniform(-180.0, 180.0)
    # Encode as simple 4-byte fixed16.16 each
    def fx(v: float) -> int:
        return int(v * 65536.0)
    info = struct.pack('>B', fmt) + struct.pack('>i', fx(lat)) + struct.pack('>i', fx(lon))
    return _tlv(127, oui + struct.pack('>B', subtype) + info)


def _lldp_end_of_lldpdu() -> bytes:
    # End of LLDPDU TLV: type=0, length=0
    return struct.pack('>BH', 0, 0)


def _build_lldp_frame(rand: random.Random) -> bytes:
    # Construct a plausible sequence of LLDP TLVs
    tlvs: List[bytes] = []
    tlvs.append(_tlv(1, _lldp_chassis_id(rand)))   # Chassis ID
    tlvs.append(_tlv(2, _lldp_port_id(rand)))      # Port ID
    tlvs.append(_tlv(3, _lldp_ttl(rand)))          # TTL
    if rand.random() < 0.7:
        tlvs.append(_tlv(4, _lldp_port_descr(rand)))
    if rand.random() < 0.8:
        tlvs.append(_tlv(5, _lldp_sys_name(rand)))
    if rand.random() < 0.5:
        tlvs.append(_tlv(6, _lldp_sys_descr(rand)))
    if rand.random() < 0.4:
        tlvs.append(_tlv(8, _lldp_mgmt_addr(rand)))
    # Organizational TLVs
    if rand.random() < 0.5:
        tlvs.append(_lldp_vlan_tlv(rand))
    if rand.random() < 0.5:
        tlvs.append(_lldp_8023_power_tlv(rand))
    if rand.random() < 0.3:
        tlvs.append(_lldp_med_location_tlv(rand))
    tlvs.append(_lldp_end_of_lldpdu())
    payload = b''.join(tlvs)
    # Optionally prepend a small header to mimic framing for lldpctl_recv streams
    if rand.random() < 0.5:
        # Simple length-prefixed chunk framing: magic + length + payload + crc32
        magic = b'LD'  # two bytes
        length = struct.pack('>H', len(payload))
        crc = struct.pack('>I', zlib.crc32(payload) & 0xFFFFFFFF)
        return magic + length + payload + crc
    return payload


def _build_atom_buffer(rand: random.Random) -> bytes:
    # Generate a buffer suitable for atom_set_buffer keys (various forms)
    choice = rand.randint(0, 8)
    if choice == 0:
        # Raw MAC address buffer
        return _mac(rand)
    if choice == 1:
        # IPv4 mgmt field packed with subtype prefix (like mgmt addr value body)
        return struct.pack('>B', 1) + _ipv4(rand)
    if choice == 2:
        # IPv6 with subtype prefix
        return struct.pack('>B', 2) + _ipv6(rand)
    if choice == 3:
        # VLAN info: VID + name
        vid = _u16(rand, 1, 4094)
        name = _str(rand, 0, 16)
        return struct.pack('>H', vid) + name
    if choice == 4:
        # Organizational TLV value body: OUI + subtype + info string
        return _oui(rand) + struct.pack('>B', rand.randint(0, 10)) + _str(rand, 0, 32)
    if choice == 5:
        # Port ID like buffer: subtype + value
        return _lldp_port_id(rand)
    if choice == 6:
        # Management address TLV value body
        return _lldp_mgmt_addr(rand)
    if choice == 7:
        # 802.3 power info body without outer TLV header
        return b"\x00\x12\x0f" + struct.pack('>B', 1) + struct.pack('>B', rand.randint(0, 3)) + struct.pack('>B', rand.randint(0, 3)) + struct.pack('>B', rand.randint(0, 8))
    # Default: printable description bytes
    return _str(rand, 0, 64)


def _assemble(rand: random.Random) -> bytes:
    # Randomly choose between emitting a stream containing one or multiple LLDP frames
    # or a single atom buffer value. This keeps inputs valid yet varied for both stubs.
    if rand.random() < 0.6:
        frames = []
        # 1 to 3 frames concatenated to simulate multiple messages in recv buffer
        for _ in range(rand.randint(1, 3)):
            frames.append(_build_lldp_frame(rand))
        data = b''.join(frames)
    else:
        data = _build_atom_buffer(rand)
    # Ensure limit <= 4096
    if len(data) > 4096:
        data = data[:4096]
    return data


def generate(seed: int) -> bytes:
    rand = random.Random(seed)
    return _assemble(rand)
